/// `body` up to (not including) a `;` that sits at bracket depth 0, or the whole string when none does.
pub(crate) fn trim_to_statement(body: &str) -> &str {
    let mut depth = 0i32;
    for (i, c) in body.char_indices() {
        match c {
            '(' | '{' | '[' => depth += 1,
            ')' | '}' | ']' => depth -= 1,
            ';' if depth <= 0 => return &body[..i],
            _ => {}
        }
    }
    body
}
